module tb;reg clk=0,rst_n=0,we=0,re=0;reg[7:0] din;wire[7:0] dout;wire full,empty;fifo dut(clk,rst_n,we,re,din,dout,full,empty);always#5 clk=~clk;task put(input[7:0] x);begin @(negedge clk);din=x;we=1;@(negedge clk);we=0;end endtask task get(input[7:0] x);begin @(negedge clk);re=1;@(negedge clk);re=0;if(dout!==x)$fatal(1,"fifo");end endtask initial begin repeat(2)@(posedge clk);rst_n=1;put(8'h11);put(8'h22);get(8'h11);get(8'h22);if(!empty)$fatal(1,"empty");$display("TB_SUMMARY total=3 errors=0");$display("PASS");$finish;end endmodule
